import{_ as p,a0 as r,w as o,s as d,ao as l,I as n,x as s,a1 as i,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"基於 FUSE 的 Bittorrent 文件系統 | LCTT x X-CMD","titleTemplate":false,"description":"基於 FUSE 的 Bittorrent 文件系統 | LCTT (201806) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"基於 FUSE 的 Bittorrent 文件系統 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"基於 FUSE 的 Bittorrent 文件系統 | LCTT (201806) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201806/20180525 A Bittorrent Filesystem Based On FUSE","title":"基於 FUSE 的 Bittorrent 文件系統","tag":"201806","desc":""},"relativePath":"201806/20180525 A Bittorrent Filesystem Based On FUSE.md","filePath":"[post].md"}'),h={name:"201806/20180525 A Bittorrent Filesystem Based On FUSE.md"};function g(b,t,k,u,c,f){const e=r("Link");return o(),d("div",null,[t[18]||(t[18]=l('<h1 id="基於-fuse-的-bittorrent-文件系統" tabindex="-1">基於 FUSE 的 Bittorrent 文件系統 <a class="header-anchor" href="#基於-fuse-的-bittorrent-文件系統" aria-label="Permalink to “基於 FUSE 的 Bittorrent 文件系統”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/05/Bittorrent-720x340.png" alt=""></p><p>Bittorrent 已經存在了很長時間，它可以從互聯網上共享和下載數據。市場上有大量的 GUI 和 CLI 的 Bittorrent 客户端。有時，你不能坐下來等待你的下載完成。你可能想要立即觀看內容。這就是 <strong>BTFS</strong> 這個不起眼的文件系統派上用場的地方。使用 BTFS，你可以將種子文件或磁力鏈接掛載為目錄，然後在文件樹中作為只讀目錄。這些文件的內容將在程序讀取時按需下載。由於 BTFS 在 FUSE 之上運行，因此不需要干預 Linux 內核。</p><h3 id="安裝-btfs" tabindex="-1">安裝 BTFS <a class="header-anchor" href="#安裝-btfs" aria-label="Permalink to “安裝 BTFS”">​</a></h3><p>BTFS 存在於大多數 Linux 發行版的默認倉庫中。</p><p>在 Arch Linux 及其變體上，運行以下命令來安裝 BTFS。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo pacman -S btfs</span></span></code></pre></div><p>在Debian、Ubuntu、Linux Mint 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt-get install btfs</span></span></code></pre></div><p>在 Gentoo 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># emerge -av btfs</span></span></code></pre></div>',11)),n("p",null,[t[1]||(t[1]=s("BTFS 也可以使用 ",-1)),i(e,{href:"https://www.ostechnix.com/linuxbrew-common-package-manager-linux-mac-os-x/"},{default:a(()=>[...t[0]||(t[0]=[s("Linuxbrew",-1)])]),_:1}),t[2]||(t[2]=s(" 包管理器進行安裝。",-1))]),t[19]||(t[19]=l('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ brew install btfs</span></span></code></pre></div><h3 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to “用法”">​</a></h3><p>BTFS 的使用非常簡單。你所要做的就是找到 .torrent 文件或磁力鏈接，並將其掛載到一個目錄中。種子文件或磁力鏈接的內容將被掛載到你選擇的目錄內。當一個程序試圖訪問該文件進行讀取時，實際的數據將按需下載。此外，像 <code>ls</code> 、<code>cat</code> 和 <code>cp</code> 這樣的工具能按照預期的方式來操作種子。像 <code>vlc</code> 和 <code>mplayer</code> 這樣的程序也可以不加修改地工作。玩家甚至不知道實際內容並非物理存在於本地磁盤中，而是根據需要從 peer 中收集。</p><p>創建一個目錄來掛載 torrent/magnet 鏈接：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mkdir mnt</span></span></code></pre></div><p>掛載 torrent/magnet 鏈接：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ btfs video.torrent mnt</span></span></code></pre></div><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/05/btfs.png" alt=""></p><p>cd 到目錄：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd mnt</span></span></code></pre></div><p>然後，開始觀看！</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vlc &lt;path-to-video.mp4&gt;</span></span></code></pre></div><p>給 BTFS 一些時間來找到並獲取網站 tracker。一旦加載了真實數據，BTFS 將不再需要 tracker。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/05/btfs-1.png" alt=""></p><p>要卸載 BTFS 文件系統，只需運行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ fusermount -u mnt</span></span></code></pre></div><p>現在，掛載目錄中的內容將消失。要再次訪問內容，你需要按照上面的描述掛載 torrent。</p><p>BTFS 會將你的 VLC 或 Mplayer 變成爆米花時間。掛載你最喜愛的電視節目或電影的種子文件或磁力鏈接，然後開始觀看，無需下載整個種子內容或等待下載完成。種子或磁力鏈接的內容將在程序訪問時按需下載。</p><p>就是這些了。希望這些有用。還會有更好的東西。敬請關注！</p><p>乾杯！</p><hr>',21)),n("p",null,[t[4]||(t[4]=s("via: ",-1)),i(e,{href:"https://www.ostechnix.com/btfs-a-bittorrent-filesystem-based-on-fuse/"},{default:a(()=>[...t[3]||(t[3]=[s("https://www.ostechnix.com/btfs-a-bittorrent-filesystem-based-on-fuse/",-1)])]),_:1})]),n("p",null,[t[9]||(t[9]=s("作者：",-1)),i(e,{href:"https://www.ostechnix.com/author/sk/"},{default:a(()=>[...t[5]||(t[5]=[s("SK",-1)])]),_:1}),t[10]||(t[10]=s(" 選題：",-1)),i(e,{href:"https://github.com/lujun9972"},{default:a(()=>[...t[6]||(t[6]=[s("lujun9972",-1)])]),_:1}),t[11]||(t[11]=s(" 譯者：",-1)),i(e,{href:"https://github.com/geekpi"},{default:a(()=>[...t[7]||(t[7]=[s("geekpi",-1)])]),_:1}),t[12]||(t[12]=s(" 校對：",-1)),i(e,{href:"https://github.com/wxy"},{default:a(()=>[...t[8]||(t[8]=[s("wxy",-1)])]),_:1})]),n("p",null,[t[15]||(t[15]=s("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[13]||(t[13]=[s("LCTT",-1)])]),_:1}),t[16]||(t[16]=s(" 原創編譯，",-1)),i(e,{href:"https://linux.cn/"},{default:a(()=>[...t[14]||(t[14]=[s("Linux中國",-1)])]),_:1}),t[17]||(t[17]=s(" 榮譽推出",-1))])])}const C=p(h,[["render",g]]);export{x as __pageData,C as default};
